//! Cargo-driven `cmipci.sys` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DriverEntry@8", 0x10000u64),
        "x86_64" => ("x86_64-pc-windows-gnu", "DriverEntry", 0x10000u64),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DriverEntry", 0x7ffb00000000u64),
        o => panic!("cmipci-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:c:stdunk", "engine:c:libcntpr", "engine:uuid", "import:portcls", "import:hal", "import:ntoskrnl", "engine:cntpr_rust", "engine:c:memcmp"],
        "x86_64" => &["engine:c:stdunk", "engine:c:libcntpr", "engine:uuid", "import:portcls", "import:hal", "import:ntoskrnl", "engine:cntpr_rust", "engine:c:memcmp"],
        "aarch64" => &["engine:c:stdunk", "engine:c:libcntpr", "engine:uuid", "import:portcls", "import:hal", "import:ntoskrnl", "engine:cntpr_rust", "engine:c:memcmp"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/drivers/wdm/audio/drivers/CMIDriver",
        "vendor/cmidriver",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["UNICODE", "WINVER=0x502", "_UNICODE", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .c_from_compile_db("cmipci_shims", &["vendor/cmidriver/adapter.cpp", "vendor/cmidriver/common.cpp", "vendor/cmidriver/mintopo.cpp", "vendor/cmidriver/minwave.cpp", "vendor/cmidriver/guid.cpp"])
        .rc("vendor/cmidriver/cmipci.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("drivers/wdm/audio/backpln/portcls/portcls.spec", "portcls.sys", "portcls")
        .import_lib("hal/hal.spec", "hal.dll", "hal")
        .import_lib("ntoskrnl/ntoskrnl.spec", "ntoskrnl.exe", "ntoskrnl")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        // cmake's kernel-mode links keep every section.
        .keep_all_sections()
        .link(ModuleKind::KernelDll {
            entry: entry.into(),
            image_base,
        });
}
